		if ( is_array( $cached ) ) {
			return $cached;
		}
		$out  = array( 'phones' => '', 'contact' => '' );
		$res  = wp_remote_get( home_url( '/' ), array( 'timeout' => 8, 'sslverify' => false ) );
		$html = is_wp_error( $res ) ? '' : (string) wp_remote_retrieve_body( $res );
		if ( $html && preg_match_all( '/href=["\\']tel:([^"\\']+)["\\']/i', $html, $m ) ) {
			$seen = array();
			foreach ( $m[1] as $raw ) {
				$digits = preg_replace( '/\\D/', '', rawurldecode( $raw ) );
				if ( strlen( $digits ) < 7 ) {
					continue;
				}
				$key = substr( $digits, -10 );
				if ( ! isset( $seen[ $key ] ) ) {
					$seen[ $key ] = 1 === count( $seen ) + 1 && 10 === strlen( $key ) ? '(' . substr( $key, 0, 3 ) . ') ' . substr( $key, 3, 3 ) . '-' . substr( $key, 6 ) : $key;
					if ( 10 === strlen( $key ) ) {
						$seen[ $key ] = '(' . substr( $key, 0, 3 ) . ') ' . substr( $key, 3, 3 ) . '-' . substr( $key, 6 );
					}
				}
			}
			// The number used most on the homepage is the main one; use only that.
			$counts = array_count_values( array_map( static function ( $r ) { return substr( preg_replace( '/\\D/', '', rawurldecode( $r ) ), -10 ); }, $m[1] ) );
			arsort( $counts );
			$main = (string) key( $counts );
			if ( isset( $seen[ $main ] ) ) {
				$out['phones'] = $seen[ $main ];
			}
		}
		foreach ( array( 'contact-us', 'contact', 'get-in-touch', 'book-now', 'book', 'request-a-quote', 'free-estimate' ) as $slug ) {
			$page = get_page_by_path( $slug );
			if ( $page && 'publish' === $page->post_status ) {
				$out['contact'] = wp_make_link_relative( get_permalink( $page ) );
				break;
			}
		}
		if ( '' === $out['contact'] ) {
			$out['contact'] = '/contact-us/';
		}
		set_transient( 'seob_ap_site_contact', $out, DAY_IN_SECONDS );
