		// Divi: full width, no duplicate page title.
		update_post_meta( $id, '_et_pb_page_layout', 'et_full_width_page' );
		update_post_meta( $id, '_et_pb_show_title', 'off' );
		self::save( array( 'hub_id' => (int) $id ) );
		return (int) $id;
	}

