	var BPROPS = PROPS.concat( [ 'borderRadius', 'paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft', 'borderWidth', 'borderStyle', 'borderColor', 'backgroundColor', 'color' ] );

	function visible( el, win ) {
