521					return new WP_Error( 'seob_ai_json', __( 'The AI answer was not valid JSON.', 'seo-boster' ) );
522				}
523				return self::finish( $state, $job, $item );
524			}
525			return array( 'done' => false, 'state' => $state );
526		}
