528		/**
529		 * Problems worth a second AI call.
530		 *
531		 * @param string[] $problems Problems.
532		 */
533		public static function hard( array $problems ) {
534			return array_values(
535				array_filter(
536					$problems,
537					static function ( $p ) {
538						if ( false !== strpos( $p, ' words, needs ' ) ) {
539							// Only far-off word counts matter (half or less of the minimum).
540							if ( preg_match( '/has (\d+) words, needs (\d+)-/', $p, $m ) ) {
541								return (int) $m[1] < (int) $m[2] * 0.5;
542							}
543							return false;
544						}
545						return false === strpos( $p, 'meta_desc is' );
546					}
547				)
548			);
549		}
