87		private static function clean_value( $prop, $v ) {
88			$v = trim( (string) $v );
89			if ( '' === $v || strlen( $v ) > 200 ) {
90				return '';
91			}
92			switch ( $prop ) {
93				case 'fontFamily':
94					return preg_match( '/^[A-Za-z0-9 ,"\'\-_.]+$/', $v ) ? $v : '';
95				case 'fontWeight':
96					return preg_match( '/^([1-9]00|normal|bold)$/', $v ) ? $v : '';
97				case 'textTransform':
98					return in_array( $v, array( 'none', 'uppercase', 'lowercase', 'capitalize' ), true ) ? $v : '';
99				case 'borderStyle':
100					return in_array( $v, array( 'none', 'solid', 'dashed', 'dotted', 'double' ), true ) ? $v : '';
101				case 'backgroundColor':
102				case 'color':
103				case 'borderColor':
104					return preg_match( '/^(#[0-9a-fA-F]{3,8}|rgba?\(\s*[\d.\s,%]+\)|transparent)$/', $v ) ? $v : '';
105				case 'lineHeight':
106				case 'letterSpacing':
107					return preg_match( '/^(normal|-?\d+(\.\d+)?(px|em|rem|%)?)$/', $v ) ? $v : '';
108				default: // Sizes, radius, padding, border width.
109					if ( preg_match( '/^-?\d+(\.\d+)?(px|em|rem|%)$/', $v ) ) {
110						return $v;
111					}
112					// "10px 20px" style shorthand (radius).
113					return preg_match( '/^(\d+(\.\d+)?(px|%)\s?){1,4}$/', $v ) ? $v : '';
114			}
115		}
