.et_mobile_menu li.seob-aws.seob-open>ul.sub-menu{display:block!important}
.et_mobile_menu li.seob-aws.menu-item-has-children>a{position:relative;padding-right:44px!important}
.et_mobile_menu li.seob-aws.menu-item-has-children>a:after{content:"";position:absolute;right:16px;top:50%;width:8px;height:8px;margin-top:-6px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg);transition:transform .2s}
