320	
321		private static function read( $file ) {
322			$path = SEOB_DIR . 'modules/area-pages/data/' . $file;
323			return is_readable( $path ) ? (string) file_get_contents( $path ) : ''; // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
324		}
325	
326		public static function divi_source() {
327			$d = json_decode( self::read( 'divi-layout.json' ), true );
328			return is_array( $d ) && ! empty( $d['data'] ) ? (string) reset( $d['data'] ) : '';
329		}
330	
331		public static function elementor_source() {
332			$d = json_decode( self::read( 'elementor-layout.json' ), true );
333			return is_array( $d ) ? $d : array();
334		}
335	
336		/**
337		 * Swap colors and fix links that point to other client sites.
338		 *
339		 * @param string $text   Layout text.
340		 * @param array  $colors old => new.
341		 */
342		public static function adapt( $text, array $colors ) {
343			foreach ( $colors as $old => $new ) {
344				if ( preg_match( '/^#[0-9a-f]{6}$/i', $old ) && preg_match( '/^#[0-9a-f]{6}$/i', $new ) ) {
345					$text = str_ireplace( $old, $new, $text );
346				}
347			}
348			$host = wp_parse_url( home_url(), PHP_URL_HOST );
349			$home = untrailingslashit( home_url() );
350			return preg_replace_callback(
351				'#https?:(\\\\?/\\\\?/)(?:www\.)?([a-z0-9.-]+\.[a-z]{2,})((?:\\\\?/[^"\'\s\]\\\\]*)*)#i',
352				static function ( $m ) use ( $host, $home ) {
353					if ( strtolower( $m[2] ) === strtolower( (string) $host ) ) {
354						return $m[0];
355					}
