		};

		var stopped = false;
		var lastText = '';
		var tick = function () {
			if (stopped) { return; }
			$.post(cfg.ajax, { action: 'seob_ap_step', nonce: cfg.nonce, job: job }).done(function (res) {
				errors = 0;
				if (!res || !res.success) { $('#seob-state').text('Error'); return; }
