658		/**
659		 * Search results for a term (photos, landscape), kept for a day so every page of a job
660		 * takes the next photos from the same list.
661		 *
662		 * @param string $term Search words.
663		 * @param int    $need Results needed (index + 1).
664		 * @return array[]|WP_Error List of [ id, title, author ].
665		 */
666		public static function magnific_results( $term, $need ) {
667			$key  = 'seob_mg_' . md5( strtolower( $term ) );
668			$list = get_transient( $key );
669			$list = is_array( $list ) ? $list : array( 'items' => array(), 'page' => 0, 'last' => 0 );
670			while ( count( $list['items'] ) < $need && ( ! $list['last'] || $list['page'] < $list['last'] ) && $list['page'] < 10 ) {
671				$data = self::magnific_get(
672					'/resources',
673					array(
674						'term'    => $term,
675						'page'    => $list['page'] + 1,
676						'limit'   => 50,
677						'order'   => 'relevance',
678						'filters' => array(
679							'content_type' => array( 'photo' => 1 ),
680							'orientation'  => array( 'landscape' => 1 ),
681						),
682					)
683				);
684				if ( is_wp_error( $data ) ) {
685					return $list['items'] ? $list['items'] : $data;
686				}
687				++$list['page'];
688				$list['last'] = isset( $data['meta']['last_page'] ) ? (int) $data['meta']['last_page'] : $list['page'];
689				$rows         = isset( $data['data'] ) && is_array( $data['data'] ) ? $data['data'] : array();
690				if ( ! $rows ) {
691					$list['last'] = $list['page'];
692				}
693				foreach ( $rows as $r ) {
694					if ( empty( $r['id'] ) ) {
695						continue;
696					}
697					$list['items'][] = array(
698						'id'     => (int) $r['id'],
699						'title'  => isset( $r['title'] ) ? sanitize_text_field( (string) $r['title'] ) : '',
700						'author' => isset( $r['author']['name'] ) ? sanitize_text_field( (string) $r['author']['name'] ) : '',
701					);
702				}
703			}
704			set_transient( $key, $list, DAY_IN_SECONDS );
705			return $list['items'];
706		}
