716		public static function magnific_download( array $item, $name, $alt ) {
717			$found = get_posts( array( 'post_type' => 'attachment', 'post_status' => 'inherit', 'meta_key' => '_seob_magnific_id', 'meta_value' => (string) (int) $item['id'], 'fields' => 'ids', 'posts_per_page' => 1 ) ); // phpcs:ignore WordPress.DB.SlowDBQuery
718			if ( $found ) {
719				return (int) $found[0];
720			}
721			$data = self::magnific_get( '/resources/' . (int) $item['id'] . '/download', array( 'image_size' => 'medium' ), 30 );
722			if ( is_wp_error( $data ) ) {
723				return $data;
724			}
725			$url = isset( $data['data']['url'] ) ? (string) $data['data']['url'] : '';
726			if ( 0 !== strpos( $url, 'https://' ) ) {
727				return new WP_Error( 'seob_magnific', 'No download link' );
728			}
729			$file = isset( $data['data']['filename'] ) ? (string) $data['data']['filename'] : '';
730			$ext  = strtolower( pathinfo( wp_parse_url( $file ? $file : $url, PHP_URL_PATH ), PATHINFO_EXTENSION ) );
731			if ( ! in_array( $ext, array( 'jpg', 'jpeg', 'png', 'webp' ), true ) ) {
732				$ext = 'jpg';
733			}
734	
735			require_once ABSPATH . 'wp-admin/includes/media.php';
736			require_once ABSPATH . 'wp-admin/includes/file.php';
737			require_once ABSPATH . 'wp-admin/includes/image.php';
738			$tmp = download_url( $url, 60 ); // Safe download: public addresses only.
739			if ( is_wp_error( $tmp ) ) {
740				return $tmp;
741			}
742			if ( ! @getimagesize( $tmp ) ) { // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged
743				wp_delete_file( $tmp );
744				return new WP_Error( 'seob_magnific', 'Not an image' );
745			}
746			$id = media_handle_sideload( array( 'name' => sanitize_file_name( $name ) . '.' . $ext, 'tmp_name' => $tmp ), 0, $alt );
747			if ( is_wp_error( $id ) ) {
748				wp_delete_file( $tmp );
749				return $id;
750			}
751			update_post_meta( $id, '_wp_attachment_image_alt', $alt );
752			update_post_meta( $id, '_seob_magnific_id', (string) (int) $item['id'] );
753			wp_update_post(
754				array(
755					'ID'           => $id,
756					'post_excerpt' => $item['author'] ? sprintf( 'Image by %s on Magnific', $item['author'] ) : 'Image from Magnific',
757				)
758			);
759			return (int) $id;
