for(const sh of document.styleSheets){let rs;try{rs=sh.cssRules}catch(e){hits.push('X '+sh.href);continue}const walk=(l,m)=>{for(const r of l){if(r.type===4){if(matchMedia(r.media.mediaText).matches)walk(r.cssRules,r.media.mediaText);continue}if(r.cssRules&&r.type!==1){walk(r.cssRules,m);continue}if(!r.selectorText)continue;let ok=false;try{ok=el.matches(r.selectorText)}catch(e){}if(ok&&(r.style.color||r.style.fontSize||r.style.borderRadius||r.style.padding))hits.push((sh.href||'inline:'+(sh.ownerNode.id||'')).split('/').pop().slice(0,50)+' | '+r.selectorText.slice(0,90)+' {color:'+r.style.color+(r.style.getPropertyPriority('color')?'!':'')+' fs:'+r.style.fontSize+(r.style.getPropertyPriority('font-size')?'!':'')+' r:'+r.style.borderRadius+'}')}};walk(rs)}
({inline: el.getAttribute('style'), hits})

