80		 * Brand colors already set on the site (Divi, Elementor kit, block theme palette).
81		 *
82		 * @return array[] label, color.
83		 */
84		public static function site_colors() {
85			$cached = get_transient( 'seob_ap_site_colors' );
86			if ( is_array( $cached ) ) {
87				return $cached;
88			}
89			$named = array();
90			if ( self::has_elementor() ) {
91				$kit = (int) get_option( 'elementor_active_kit' );
92				$ps  = $kit ? get_post_meta( $kit, '_elementor_page_settings', true ) : array();
93				if ( ! empty( $ps['system_colors'] ) && is_array( $ps['system_colors'] ) ) {
94					foreach ( $ps['system_colors'] as $c ) {
95						if ( ! empty( $c['color'] ) ) {
96							$named[] = array( 'label' => 'Elementor ' . ( isset( $c['title'] ) ? $c['title'] : '' ), 'color' => $c['color'] );
97						}
98					}
99				}
100			}
101			$divi = get_option( 'et_divi', array() );
102			if ( is_array( $divi ) ) {
103				foreach ( array( 'accent_color' => 'Divi accent', 'all_buttons_bg_color' => 'Divi buttons', 'link_color' => 'Divi links', 'primary_nav_bg' => 'Divi menu', 'footer_bg' => 'Divi footer' ) as $k => $label ) {
104					if ( ! empty( $divi[ $k ] ) && is_string( $divi[ $k ] ) ) {
105						$named[] = array( 'label' => $label, 'color' => $divi[ $k ] );
106					}
107				}
108			}
109			if ( function_exists( 'wp_get_global_settings' ) && ! self::has_divi() ) {
110				foreach ( (array) wp_get_global_settings( array( 'color', 'palette', 'theme' ) ) as $c ) {
111					if ( ! empty( $c['color'] ) ) {
112						$named[] = array( 'label' => 'Theme ' . ( isset( $c['name'] ) ? $c['name'] : '' ), 'color' => $c['color'] );
113					}
114				}
115			}
116	
117			// The colors the homepage actually uses most are the real brand colors.
118			$used = array();
119			$res  = wp_remote_get( home_url( '/' ), array( 'timeout' => 8, 'sslverify' => false ) );
120			if ( ! is_wp_error( $res ) && 200 === (int) wp_remote_retrieve_response_code( $res ) ) {
121				preg_match_all( '/#[0-9a-fA-F]{6}\b/', (string) wp_remote_retrieve_body( $res ), $m );
122				foreach ( $m[0] as $c ) {
123					$c = strtolower( $c );
124					if ( ! self::is_neutral( $c ) && ! in_array( $c, self::builder_defaults(), true ) ) {
125						$used[ $c ] = isset( $used[ $c ] ) ? $used[ $c ] + 1 : 1;
126					}
127				}
128				arsort( $used );
129			}
130	
131			$out  = array();
132			$seen = array();
133			$add  = static function ( $label, $color ) use ( &$out, &$seen ) {
134				$k = strtolower( (string) $color );
135				if ( ! preg_match( '/^#[0-9a-f]{6}$/', $k ) || isset( $seen[ $k ] ) ) {
136					return;
137				}
138				$seen[ $k ] = true;
139				$out[]      = array( 'label' => $label, 'color' => $k );
140			};
141			foreach ( array_slice( $used, 0, 6, true ) as $c => $n ) {
142				$add( sprintf( 'Used on homepage (%d times)', $n ), $c );
143			}
144			foreach ( $named as $c ) {
145				$add( trim( $c['label'] ), $c['color'] );
146			}
147			$add( 'Black', '#111111' );
148			$add( 'White', '#ffffff' );
149			$out = array_slice( $out, 0, 10 );
150			set_transient( 'seob_ap_site_colors', $out, 12 * HOUR_IN_SECONDS );
151			return $out;
152		}
153	
154		public static function accent() {
155			$a = self::settings()['accent'];
156			if ( preg_match( '/^#[0-9a-f]{6}$/i', (string) $a ) ) {
157				return $a;
158			}
159			$colors = self::site_colors();
160			// Prefer colors named like a brand color, then any strong color. Skip pale ones.
161			usort(
162				$colors,
163				static function ( $a, $b ) {
164					$score = static function ( $c ) {
165						return preg_match( '/primary|accent|brand|button|secondary/i', $c['label'] ) ? 0 : 1;
166					};
167					return $score( $a ) <=> $score( $b );
168				}
169			);
170			foreach ( $colors as $c ) {
171				if ( 7 === strlen( $c['color'] ) && ! self::is_neutral( $c['color'] ) && self::luminance( $c['color'] ) < 0.6 ) {
172					return $c['color'];
173				}
174			}
175			return '#1e73be';
176		}
177	
178		/**
179		 * Second brand color: the next strong site color that differs enough from the first.
180		 *
181		 * @param string $accent First brand color.
182		 */
183		public static function accent2( $accent ) {
184			list( $r1, $g1, $b1 ) = self::rgb( $accent );
185			foreach ( self::site_colors() as $c ) {
186				if ( 7 !== strlen( $c['color'] ) || self::is_neutral( $c['color'] ) || strtolower( $c['color'] ) === strtolower( $accent ) ) {
187					continue;
188				}
189				list( $r2, $g2, $b2 ) = self::rgb( $c['color'] );
190				// Dark enough for white button text, and clearly a different shade.
191				if ( abs( $r1 - $r2 ) + abs( $g1 - $g2 ) + abs( $b1 - $b2 ) > 60 && self::luminance( $c['color'] ) < 0.35 ) {
192					return $c['color'];
193				}
194			}
195			// No second color on the site: a darker shade of the first.
196			return sprintf( '#%02x%02x%02x', (int) ( $r1 * 0.7 ), (int) ( $g1 * 0.7 ), (int) ( $b1 * 0.7 ) );
197		}
198	
199		/** Builder default colors that are not the site's brand. */
200		private static function builder_defaults() {
201			return array( '#2ea3f2', '#7ebec5', '#82c0c7', '#0c71c3', '#6ec1e4', '#54595f', '#7a7a7a', '#61ce70' );
202		}
203	
204		/**
205		 * Color map that turns the saved layout's colors into this site's brand colors.
206		 *
207		 * @param string $which divi|elementor.
208		 */
209		public static function auto_color_map( $which ) {
210			$accent  = self::accent();
211			$accent2 = self::accent2( $accent );
212			if ( 'divi' === $which ) {
213				// The SCO layout: #947d65 main, #5d7e81 second, #367b42 call-to-action fallback.
214				return array(
215					'#947d65' => $accent,
216					'#5d7e81' => $accent2,
217					'#367b42' => $accent2,
218				);
219			}
220			$src = self::layout_colors( (string) wp_json_encode( self::elementor_source() ) );
221			$map = array();
222			if ( isset( $src[0] ) ) {
223				$map[ $src[0] ] = $accent;
224			}
225			if ( isset( $src[1] ) ) {
226				$map[ $src[1] ] = $accent2;
227			}
228			return $map;
229		}
230	
231		/**
232		 * Pick the right design for this site automatically:
233		 * Divi -> Divi Theme Builder template, Elementor Pro -> Elementor single template, anything else -> built-in layout.
234		 * An existing template is kept (so edits made in Theme Builder are never overwritten).
235		 *
236		 * @param bool $force Install a fresh copy even if one exists.
237		 * @return array mode and message.
238		 */
239		public static function auto_install( $force = false ) {
240			$s = self::settings();
241			if ( self::has_divi() ) {
242				if ( ! $force && $s['divi_template'] && 'publish' === get_post_status( $s['divi_template'] ) ) {
243					self::repair_divi_template();
244					self::save( array( 'mode' => 'divi' ) );
245					return array( 'mode' => 'divi', 'message' => 'kept' );
246				}
247				$r = self::install_divi( self::auto_color_map( 'divi' ) );
248				return is_wp_error( $r ) ? array( 'mode' => 'builtin', 'message' => $r->get_error_message() ) : array( 'mode' => 'divi', 'message' => 'installed' );
249			}
250			if ( self::has_elementor_pro() ) {
251				if ( ! $force && $s['el_template'] && 'publish' === get_post_status( $s['el_template'] ) ) {
252					self::save( array( 'mode' => 'elementor' ) );
253					return array( 'mode' => 'elementor', 'message' => 'kept' );
254				}
255				$r = self::install_elementor( self::auto_color_map( 'elementor' ) );
256				return is_wp_error( $r ) ? array( 'mode' => 'builtin', 'message' => $r->get_error_message() ) : array( 'mode' => 'elementor', 'message' => 'installed' );
257			}
258			self::save( array( 'mode' => 'builtin' ) );
259			return array( 'mode' => 'builtin', 'message' => 'builtin' );
260		}
261	
262		/** Where the design is edited, for links in the admin. */
